      const v = args[field];
      if (v === undefined || v === null || v === "") {
        return { ok: false, error: "缺少必填字段：" + field };
      }
    }
  }

  if (schema.properties) {
    for (const [key, prop] of Object.entries(schema.properties)) {
      const v = args[key];
      if (v === undefined || v === null) continue;
      if (prop.type) {
        const expected = prop.type === "integer" ? "number" : prop.type;
        if (expected === "number" && typeof v !== "number") {
          return { ok: false, error: "字段 " + key + " 类型错误，期望 number" };
        }
        if (expected === "array" && !Array.isArray(v)) {
          return { ok: false, error: "字段 " + key + " 类型错误，期望 array" };
        }
        if (expected === "string" && typeof v !== "string") {
          return { ok: false, error: "字段 " + key + " 类型错误，期望 string" };
        }
        if (expected === "boolean" && typeof v !== "boolean") {
          return { ok: false, error: "字段 " + key + " 类型错误，期望 boolean" };
        }
      }
      // 数组**元素**类型校验：schema 已声明 items:{type:"string"} 时，
      // 只校验顶层 array 类型是不够的 —— 元素类型不符会一路传到 Node 内部
      // 才报错（例：flow_check_scope 的 paths:["README.md",123] 会抛
      // "The \"path\" argument must be of type string" 这种底层错误），
      // 调用方拿到的是不可读的堆栈信息。改为在入口就给出明确提示。
      // 注意：**null 也要拦**（typeof null !== "string"）—— 否则 unknowns=[null]
      // 这类值会静默落盘（虽然不参与档位必填、不进 executor 合同文本，
      // 但会在 flow_status 回显整卡时露出 null 元素）。
      if (prop.type === "array" && Array.isArray(v) && prop.items && prop.items.type) {
        const want = prop.items.type === "integer" ? "number" : prop.items.type;
        for (let i = 0; i < v.length; i++) {
          const el = v[i];
          if (el === undefined) continue;
          const bad =
            (want === "number" && typeof el !== "number") ||
            (want === "string" && typeof el !== "string") ||
            (want === "boolean" && typeof el !== "boolean") ||
            (want === "object" && (typeof el !== "object" || el === null || Array.isArray(el)));
          if (bad) {
            return { ok: false, error: "字段 " + key + "[" + i + "] 类型错误，期望 " + want };
          }
        }
      }
      if (prop.enum && !prop.enum.includes(v)) {
        return { ok: false, error: "字段 " + key + " 值非法，可选：" + prop.enum.join(", ") };
      }
    }
  }
  return { ok: true };
}

// ---- CallTool：先校验参数，再分发到工具 handler ----
async function callTool(toolName, args) {
  const t = TOOLS.find((x) => x.name === toolName);
  if (!t) {
    return { content: [{ type: "text", text: "Unknown tool: " + toolName }], isError: true };
  }

  const validation = validateToolArgs(toolName, args);
  if (!validation.ok) {
    return { content: [{ type: "text", text: "ERROR: " + validation.error }], isError: true };
  }

  // 项目级敏感路径扩展：从 cwd 逐级向上找 `.carlos.json`（只追加，不能缩减）。
  // 放在这里统一加载，保证同一请求里所有路径判定用同一份规则；
  // 配置缺失 / 损坏时自动退回内置基线，不影响门禁。
  try {
    loadProjectSensitiveConfig(typeof args.cwd === "string" && args.cwd ? args.cwd : process.cwd());
  } catch { /* 配置不可读：保持内置基线 */ }

  try {
    return await t.handler(args);
  } catch (e) {
    const err = e && e.message ? e.message : String(e);
    return {
      content: [{ type: "text", text: "ERROR: " + formatError(err) }],
      isError: true,
    };
  }
}

// ---- 传输模式：stdio（逐行 JSON-RPC 2.0） ----
// 启动日志必须在 await 之前写：serveStdio 会一直阻塞到 stdin 关闭（宿主退出），
// 写在后面等于「只在退出时打印」，排查时看不到任何启动痕迹。
process.stderr.write("carlos-flow MCP server ready (stdio)\n");
// ⚠️ 这里**不能**用顶层 await。
// 实测（2026-11-17）：Cindy 的随包 Node 进程用 require() 加载入口，
// ESM 图里只要有顶层 await，require 就抛 ERR_REQUIRE_ASYNC_MODULE，
// 插件表现为「一调就 Node 工作进程已退出」。
// serveStdio 返回的 Promise 不 await 也没关系：readline 订阅着 stdin，
// 进程不会被事件循环判定为空闲而退出；失败走 catch 落 stderr + 非零退出码。
serveStdio({
  name: "carlos-flow",
  version: pkgVersion,
  tools: TOOL_SCHEMAS,
  callTool,
  log,
}).catch((e) => {
  try {
    process.stderr.write("[carlos-flow] stdio 服务端异常退出：" + (e && e.message ? e.message : e) + "\n");
  } catch { /* stderr 不可写时静默 */ }
  process.exitCode = 1;
});

# Carlos Flow 安装指南

本指南说明如何把 Carlos Flow 接入 Cursor、VS Code、Windsurf 等编程平台。

## 准备工作

1. 确认已安装 **Node.js 18+**（`node -v`）。
2. 准备一个 Token 字符串（自行生成，例如 `openssl rand -hex 16`），客户端与 Bridge 用同一个。
3. 记下 Carlos Flow 项目的安装路径，下文记为 `<INSTALL_PATH>`（即你 clone 下来的项目根目录）。

> **Bridge 自带路径自探测**：只要 `<INSTALL_PATH>/bridge/mcp-bridge.js` 在正确位置，
> Bridge 会自动定位同级的 `src/index.js`，**不需要**再手动设置 `CARLOS_FLOW_MCP_ROOT`。
> 该环境变量仅在项目被拆分到其他目录时才需要保留。

---

## 1. Cursor

写入 `.cursor/mcp.json`（文件不存在则新建）：

```json
{
  "mcpServers": {
    "carlos-flow": {
      "command": "node",
      "args": ["<INSTALL_PATH>/bridge/mcp-bridge.js"],
      "env": {
        "CARLOS_BRIDGE_TOKEN": "YOUR_TOKEN_HERE"
      }
    }
  }
}
```

## 2. VS Code

写入 `.vscode/settings.json`：

```json
{
  "mcp.servers": {
    "carlos-flow": {
      "command": "node",
      "args": ["<INSTALL_PATH>/bridge/mcp-bridge.js"],
      "env": {
        "CARLOS_BRIDGE_TOKEN": "YOUR_TOKEN_HERE"
      }
    }
  }
}
```

## 3. Windsurf

写入 `~/.windsurf/mcp.json`：

```json
{
  "mcpServers": {
    "carlos-flow": {
      "command": "node",
      "args": ["<INSTALL_PATH>/bridge/mcp-bridge.js"],
      "env": {
        "CARLOS_BRIDGE_TOKEN": "YOUR_TOKEN_HERE"
      }
    }
  }
}
```

---

## 配置自检

配置完成后，可在项目目录运行：

```bash
./check-all.sh
```

它会做两件事：

1. `node --check` 校验 `bridge/mcp-bridge.js`、`src/index.js`、`smoke-test.js` 语法；
2. **真 RPC 往返冒烟测试**：真起一个 Bridge，发 `initialize` + `tools/list`，
   断言能拿回全部 **19 个工具**。这排除了「进程起来了但转发断了」的假阳性。

预期输出：

```
✅ initialize 握手成功
>>> RPC 往返总耗时：360.98ms
>>> 发现工具数：19
🎉 深度兼容性验证通过（真 RPC 往返拿到 19 个工具）
```

## 常见问题

| 现象 | 原因 | 处理 |
| :--- | :--- | :--- |
| Bridge 启动即退出，日志提示 `CARLOS_BRIDGE_TOKEN 未设置` | 客户端配置里没传 Token | 按上面的 `env` 补上 |
| 日志提示 `MCP server 子进程启动失败` | 项目目录不完整，或 `src/index.js` 不在 Bridge 同级父目录 | 确认 `<INSTALL_PATH>/src/index.js` 存在；必要时设 `CARLOS_FLOW_MCP_ROOT` |
| 连上了但工具列表为空 | 客户端没带 `_token` | 检查客户端是否按 MCP 规范在请求里传 Token |
| Windows 上 Bridge 重启时弹黑框 | 已修复 | 升级到 **v2.11.2 及以上**（`windowsHide: true`） |
